import type { EvalReport, Indicator, Landscape, SampleMessage } from '@akshi/contracts';
import evalReport from './eval-report.json';
import riskCalibration from './risk-calibration.json';
import indicators from './indicators.json';
import landscape from './landscape.json';
import samples from './samples.json';

/**
 * Sample indicators: invented scam UPI IDs, phone numbers and domains taken from the synthetic dataset
 * (data/messages), grouped into named campaigns. `reports` counts dataset rows, not real reports.
 * Generated by ml/akshi_ml/export_content.py; do not edit indicators.json by hand.
 */
export const INDICATORS: Indicator[] = indicators as Indicator[];

/**
 * Sample chips for the scan page. Written by hand for the demo; none is a row of the training split
 * (ml/tests/test_content.py checks this). The three genuine ones must come out as "No warning signs found".
 */
export const SAMPLE_MESSAGES: SampleMessage[] = samples as SampleMessage[];

/** Counts of scam rows in the synthetic dataset by category, language and channel. Sample data. */
export const LANDSCAPE: Landscape = landscape as Landscape;

/**
 * Results of running the shipped engine over the held-out data, written by the eval harness (npm run eval).
 * Its `notes` say plainly when a run used the placeholder engine. Validated against EvalReportSchema in tests.
 */
export const EVAL_REPORT: EvalReport = evalReport as EvalReport;
/** How often each risk band was really a scam on the test split (npm run reliability -w @akshi/eval). */
export const RISK_CALIBRATION = riskCalibration;
